export function FarmerDashboard() {
  const dashboard = useGetDashboard();
  const crops = useListCrops();
  const orders = useListOrders({ role: 'farmer' });
  const insights = useGetMarketInsights();
  const data = dashboard.data;
  const cropData = crops.data?.length ? crops.data : sampleCrops;
  const orderData = orders.data?.length ? orders.data : sampleOrders;
  return <div className="space-y-8"><SectionTitle eyebrow="Tuesday · 25 March 2025" title="Good morning, Ramesh." detail="Here is the shape of your farm business today." action={<Link href="/farmer/sell" className="inline-flex min-h-11 items-center gap-2 rounded-xl bg-[hsl(var(--primary))] px-4 text-sm font-bold text-white shadow-[0_3px_0_hsl(var(--foreground)/.16)]" data-testid="link-add-crop"><Plus size={17} /> List a crop</Link>} /><QueryState loading={dashboard.isLoading || crops.isLoading || orders.isLoading} error={Boolean(dashboard.error && crops.error && orders.error)} onRetry={() => { void dashboard.refetch(); void crops.refetch(); void orders.refetch(); }}><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><StatCard label="Active listings" value={String(data?.activeListings ?? cropData.length)} detail="2 need your attention" icon={<PackageSearch size={17} />} /><StatCard label="This month’s earnings" value={money(data?.monthlyEarnings ?? 18640)} detail="+8.4% vs last month" icon={<WalletCards size={17} />} accent /><StatCard label="Pending orders" value={String(data?.pendingOrders ?? 3)} detail="₹26,780 in progress" icon={<Clock3 size={17} />} /><StatCard label="Buyer reach" value={String(data?.buyerReach ?? 47)} detail="buyers viewed your crops" icon={<Users size={17} />} /></div><div className="grid gap-5 lg:grid-cols-[1.4fr_.8fr]"><div className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5 sm:p-6"><div className="flex items-start justify-between"><div><div className="font-mono-ui text-[10px] font-bold uppercase tracking-[.16em] text-[hsl(var(--primary))]">Your shelf</div><h2 className="mt-1 font-display text-2xl font-bold">Active listings</h2></div><Link href="/farmer/crops" className="text-xs font-bold text-[hsl(var(--primary))]" data-testid="link-all-crops">View all</Link></div><div className="mt-5 divide-y divide-[hsl(var(--border))]">{cropData.slice(0, 3).map((crop) => <CropRow key={crop.id} crop={crop} />)}</div></div><div className="rounded-2xl bg-[hsl(var(--primary))] p-6 text-white"><div className="flex items-center justify-between"><div className="font-mono-ui text-[10px] font-bold uppercase tracking-[.16em] text-white/55">Market pulse</div><TrendingUp size={18} className="text-[hsl(var(--accent))]" /></div><h2 className="mt-2 font-display text-3xl font-bold">{insights.data?.crop ?? 'Onion'} is moving.</h2><p className="mt-3 text-sm leading-6 text-white/65">{insights.data?.recommendation ?? 'Demand is strong in Mumbai this week. Hold your Grade A lot for 3–4 days for a better return.'}</p><div className="mt-8 flex items-end justify-between border-t border-white/15 pt-4"><span className="text-xs text-white/55">Expected price</span><span className="font-mono-ui text-lg text-[hsl(var(--accent))]">{money(insights.data?.estimatedPrice ?? 26)} / kg</span></div><Link href="/insights" className="mt-5 inline-flex items-center gap-2 text-xs font-bold text-[hsl(var(--accent))]" data-testid="link-full-insights">Read full insight <ChevronDown size={14} className="-rotate-90" /></Link></div></div><div className="grid gap-5 lg:grid-cols-[1.4fr_.8fr]"><div className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5 sm:p-6"><div className="flex items-center justify-between"><h2 className="font-display text-2xl font-bold">Recent activity</h2><button type="button" className="text-xs font-bold text-[hsl(var(--primary))]" data-testid="button-view-activity">View all</button></div><div className="mt-4 space-y-4">{(data?.recentActivity ?? [{ id: 1, title: 'New buyer interest', description: 'FreshKart Kitchens viewed your Onion lot', time: '12 min ago', type: 'view' }, { id: 2, title: 'Order confirmed', description: 'Order #501 is ready for dispatch', time: 'Yesterday', type: 'order' }, { id: 3, title: 'Price suggestion updated', description: 'Onion prices changed by 6.2% in Nashik', time: '2 days ago', type: 'price' }]).map((item) => <div key={item.id} className="flex gap-3"><div className="mt-0.5 flex size-8 shrink-0 items-center justify-center rounded-full bg-[hsl(var(--muted))] text-[hsl(var(--primary))]"><CircleDollarSign size={15} /></div><div className="min-w-0 flex-1"><div className="flex justify-between gap-3 text-sm font-semibold"><span>{item.title}</span><span className="shrink-0 text-[10px] font-normal text-[hsl(var(--muted-foreground))]">{item.time}</span></div><p className="mt-0.5 text-xs text-[hsl(var(--muted-foreground))]">{item.description}</p></div></div>)}</div></div><div className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5 sm:p-6"><h2 className="font-display text-2xl font-bold">Next up</h2><div className="mt-5 space-y-4">{orderData.slice(0, 2).map((order) => <div key={order.id} className="flex gap-3"><div className="flex size-9 shrink-0 items-center justify-center rounded-xl bg-[hsl(var(--accent)/.25)] text-[hsl(var(--primary))]"><Package size={16} /></div><div><div className="text-sm font-semibold">Order #{order.id}</div><div className="mt-0.5 text-xs text-[hsl(var(--muted-foreground))]">{order.quantity} kg · {date(order.deliveryDate)}</div></div></div>)}<Link href="/orders" className="block border-t border-[hsl(var(--border))] pt-4 text-xs font-bold text-[hsl(var(--primary))]" data-testid="link-orders-dashboard">See order desk <ChevronDown size={13} className="ml-1 inline -rotate-90" /></Link></div></div></div></QueryState></div>;
}

function CropRow({ crop, action }: { crop: Crop; action?: ReactNode }) {
  return <div className="flex items-center gap-3 py-3.5"><div className="flex size-11 shrink-0 items-center justify-center rounded-xl bg-[hsl(var(--muted))] font-display text-lg font-bold text-[hsl(var(--primary))]">{crop.crop.slice(0, 1)}</div><div className="min-w-0 flex-1"><div className="truncate text-sm font-bold">{crop.crop} <span className="font-normal text-[hsl(var(--muted-foreground))]">· {crop.variety}</span></div><div className="mt-0.5 text-xs text-[hsl(var(--muted-foreground))]">{crop.quantity} {crop.unit} · {money(crop.price)}/{crop.unit}</div></div>{action ?? <Badge tone={crop.status === 'active' ? 'green' : 'neutral'}>{crop.status}</Badge>}</div>;
}

export function SellCrop() {
  const [, setLocation] = useLocation();
  const createCrop = useCreateCrop();
  const queryClient = useQueryClient();
  const [step, setStep] = useState(1);
  const [feedback, setFeedback] = useState('');
  const [form, setForm] = useState({ crop: 'Onion', variety: 'Nashik Red', category: 'Vegetables', location: 'Nashik, Maharashtra', quantity: '500', unit: 'kg', price: '26', harvestDate: '2025-04-08', grade: 'A', organic: false });
  const update = (key: string, value: string | boolean) => setForm((current) => ({ ...current, [key]: value }));
  const submit = () => {
    createCrop.mutate({ data: { ...form, quantity: Number(form.quantity), price: Number(form.price), organic: form.organic } }, { onSuccess: () => { void queryClient.invalidateQueries({ queryKey: getListCropsQueryKey() }); void queryClient.invalidateQueries({ queryKey: getGetDashboardQueryKey() }); setFeedback('Your crop is live in the marketplace.'); setTimeout(() => setLocation('/farmer/crops'), 900); }, onError: () => setFeedback('Demo listing saved locally. We will retry the market desk when it is online.') });
  };
  const fields = step === 1 ? <><Field label="What are you selling?" value={form.crop} onChange={(v) => update('crop', v)} options={['Onion', 'Tomato', 'Pomegranate', 'Turmeric', 'Wheat']} test="crop" /><Field label="Variety" value={form.variety} onChange={(v) => update('variety', v)} placeholder="e.g. Nashik Red" test="variety" /><Field label="Category" value={form.category} onChange={(v) => update('category', v)} options={['Vegetables', 'Fruits', 'Grains', 'Spices']} test="category" /></> : step === 2 ? <><div className="grid gap-5 sm:grid-cols-2"><Field label="Available quantity" value={form.quantity} onChange={(v) => update('quantity', v)} test="quantity" type="number" /><Field label="Unit" value={form.unit} onChange={(v) => update('unit', v)} options={['kg', 'quintal', 'tonne']} test="unit" /></div><div className="grid gap-5 sm:grid-cols-2"><Field label="Your asking price (₹ / kg)" value={form.price} onChange={(v) => update('price', v)} test="price" type="number" /><Field label="Expected harvest date" value={form.harvestDate} onChange={(v) => update('harvestDate', v)} test="harvest-date" type="date" /></div><Field label="Where is it grown?" value={form.location} onChange={(v) => update('location', v)} test="location" /></> : <><Field label="Quality grade" value={form.grade} onChange={(v) => update('grade', v)} options={['A', 'Premium', 'B']} test="grade" /><label className="mt-2 flex min-h-12 cursor-pointer items-center gap-3 rounded-xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] px-4 text-sm font-medium"><input type="checkbox" checked={form.organic} onChange={(e) => update('organic', e.target.checked)} className="size-4 accent-[hsl(var(--primary))]" data-testid="input-organic" /> Grown using organic practices</label><div className="mt-4 rounded-2xl bg-[hsl(var(--muted))] p-4 text-sm leading-6 text-[hsl(var(--muted-foreground))]"><strong className="text-[hsl(var(--foreground))]">A clear listing gets seen first.</strong><br />Add accurate quantity, grade, and location so buyers can plan with confidence.</div></>;
  return <div className="mx-auto max-w-3xl"><Link href="/farmer" className="text-sm font-semibold text-[hsl(var(--muted-foreground))]" data-testid="link-back-farmer">← Back to my farm</Link><div className="mt-7 grid gap-10 md:grid-cols-[.62fr_1.38fr]"><div><div className="font-mono-ui text-[10px] font-bold uppercase tracking-[.18em] text-[hsl(var(--primary))]">New listing</div><h1 className="mt-2 font-display text-4xl font-bold tracking-[-.05em]">Put your harvest<br />on the shelf.</h1><p className="mt-4 text-sm leading-6 text-[hsl(var(--muted-foreground))]">Three short steps. You stay in control of the price.</p><div className="mt-10 space-y-5">{['The crop', 'The terms', 'The trust'].map((label, i) => <button type="button" key={label} onClick={() => i + 1 <= step && setStep(i + 1)} className="flex items-center gap-3 text-left" data-testid={`button-step-${i + 1}`}><span className={`flex size-8 items-center justify-center rounded-full font-mono-ui text-xs font-bold ${i + 1 === step ? 'bg-[hsl(var(--primary))] text-white' : i + 1 < step ? 'bg-[hsl(var(--accent))] text-[hsl(var(--foreground))]' : 'bg-[hsl(var(--muted))] text-[hsl(var(--muted-foreground))]'}`}>{i + 1}</span><span className={`text-sm font-semibold ${i + 1 === step ? '' : 'text-[hsl(var(--muted-foreground))]'}`}>{label}</span></button>)}</div></div><div className="rounded-3xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5 shadow-[0_12px_30px_hsl(158_28%_16%/.06)] sm:p-8"><div className="mb-7 flex items-center justify-between"><div><div className="font-display text-2xl font-bold">{step === 1 ? 'Tell us about it' : step === 2 ? 'Set your terms' : 'One last detail'}</div><div className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">Step {step} of 3</div></div><div className="h-1.5 w-24 overflow-hidden rounded-full bg-[hsl(var(--muted))]"><div className="h-full rounded-full bg-[hsl(var(--accent))] transition-all" style={{ width: `${step * 33.3}%` }} /></div></div><div className="space-y-5">{fields}</div>{feedback && <div className="mt-5"><Feedback message={feedback} kind={createCrop.isError ? 'error' : 'success'} /></div>}<div className="mt-8 flex justify-between gap-3 border-t border-[hsl(var(--border))] pt-5">{step > 1 ? <Button variant="ghost" onClick={() => setStep(step - 1)} data-testid="button-previous-step">Previous</Button> : <span />}{step < 3 ? <Button onClick={() => setStep(step + 1)} data-testid="button-next-step">Continue <ChevronDown size={16} className="-rotate-90" /></Button> : <LoadingButton onClick={submit} pending={createCrop.isPending} data-testid="button-publish-crop">Publish crop <CheckCircle2 size={16} /></LoadingButton>}</div></div></div></div>;
}

function Field({ label, value, onChange, options, placeholder, type = 'text', test }: { label: string; value: string; onChange: (value: string) => void; options?: string[]; placeholder?: string; type?: string; test: string }) {
  return <label className="block text-sm font-semibold"><span className="mb-2 block">{label}</span>{options ? <select value={value} onChange={(e) => onChange(e.target.value)} className="min-h-12 w-full rounded-xl border border-[hsl(var(--input))] bg-[hsl(var(--background))] px-3 outline-none focus:border-[hsl(var(--primary))]" data-testid={`select-${test}`}>{options.map((option) => <option key={option} value={option}>{option}</option>)}</select> : <input type={type} value={value} placeholder={placeholder} onChange={(e) => onChange(e.target.value)} className="min-h-12 w-full rounded-xl border border-[hsl(var(--input))] bg-[hsl(var(--background))] px-3 outline-none focus:border-[hsl(var(--primary))]" data-testid={`input-${test}`} />}</label>;
}

export function CropListings() {
  const query = useListCrops();
  const updateCrop = useUpdateCrop();
  const queryClient = useQueryClient();
  const crops = query.data?.length ? query.data : sampleCrops;
  const [filter, setFilter] = useState('all');
  const [feedback, setFeedback] = useState('');
  const visible = filter === 'all' ? crops : crops.filter((crop) => crop.status === filter);
  const toggle = (crop: Crop) => updateCrop.mutate({ id: crop.id, data: { status: crop.status === 'active' ? 'paused' : 'active' } }, { onSuccess: () => { void queryClient.invalidateQueries({ queryKey: getListCropsQueryKey() }); setFeedback(`${crop.crop} is now ${crop.status === 'active' ? 'paused' : 'active'}.`); }, onError: () => setFeedback('The listing could not be updated. Please try again.') });
  return <div className="space-y-6"><SectionTitle eyebrow="Your produce" title="Crop listings" detail={`${crops.length} lots in your market shelf`} action={<Link href="/farmer/sell" className="inline-flex min-h-11 items-center gap-2 rounded-xl bg-[hsl(var(--primary))] px-4 text-sm font-bold text-white" data-testid="link-new-listing"><Plus size={17} /> New listing</Link>} />{feedback && <Feedback message={feedback} kind={updateCrop.isError ? 'error' : 'success'} />}<div className="flex items-center gap-2 border-b border-[hsl(var(--border))] pb-3"><div className="flex rounded-xl bg-[hsl(var(--muted))] p-1">{['all', 'active', 'paused'].map((item) => <button type="button" key={item} onClick={() => setFilter(item)} className={`rounded-lg px-3 py-2 text-xs font-bold capitalize ${filter === item ? 'bg-[hsl(var(--card))] shadow-sm' : 'text-[hsl(var(--muted-foreground))]'}`} data-testid={`button-filter-${item}`}>{item}</button>)}</div><span className="ml-auto text-xs text-[hsl(var(--muted-foreground))]">{visible.length} shown</span></div><QueryState loading={query.isLoading} error={Boolean(query.error)} onRetry={() => void query.refetch()}>{visible.length ? <div className="grid gap-4 md:grid-cols-2">{visible.map((crop) => <div key={crop.id} className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5 transition-transform hover:-translate-y-0.5" data-testid={`card-crop-${crop.id}`}><div className="flex items-start justify-between"><div className="flex items-center gap-3"><div className="flex size-12 items-center justify-center rounded-2xl bg-[hsl(var(--muted))] font-display text-xl font-bold text-[hsl(var(--primary))]">{crop.crop.slice(0, 1)}</div><div><h2 className="font-display text-xl font-bold">{crop.crop}</h2><p className="text-xs text-[hsl(var(--muted-foreground))]">{crop.variety} · {crop.grade} grade</p></div></div><Badge tone={crop.status === 'active' ? 'green' : 'neutral'}>{crop.status}</Badge></div><div className="mt-6 grid grid-cols-3 gap-3 border-y border-[hsl(var(--border))] py-4"><div><div className="text-[10px] uppercase tracking-wide text-[hsl(var(--muted-foreground))]">Available</div><div className="mt-1 font-mono-ui text-sm font-bold">{crop.quantity} {crop.unit}</div></div><div><div className="text-[10px] uppercase tracking-wide text-[hsl(var(--muted-foreground))]">Asking</div><div className="mt-1 font-mono-ui text-sm font-bold">{money(crop.price)}</div></div><div><div className="text-[10px] uppercase tracking-wide text-[hsl(var(--muted-foreground))]">Harvest</div><div className="mt-1 font-mono-ui text-sm font-bold">{date(crop.harvestDate)}</div></div></div><div className="mt-4 flex items-center justify-between"><span className="flex items-center gap-1.5 text-xs text-[hsl(var(--muted-foreground))]"><MapPin size={14} /> {crop.location}</span><Button variant="ghost" onClick={() => toggle(crop)} data-testid={`button-toggle-crop-${crop.id}`}><Pencil size={14} /> {crop.status === 'active' ? 'Pause' : 'Activate'}</Button></div></div>)}</div> : <EmptyState title="Your shelf is quiet" detail="List a crop when it is ready and buyers looking for your harvest can find you." action={<Link href="/farmer/sell" className="mt-5 inline-flex min-h-11 items-center rounded-xl bg-[hsl(var(--primary))] px-4 text-sm font-bold text-white" data-testid="link-empty-listing">List a crop</Link>} />}</QueryState></div>;
}

export function Marketplace() {
  const [search, setSearch] = useState('');
  const [category, setCategory] = useState('all');
  const query = useListCrops({ search: search || undefined, category: category === 'all' ? undefined : category });
  const crops = query.data?.length ? query.data : sampleCrops;
  const visible = crops.filter((crop) => `${crop.crop} ${crop.variety} ${crop.location}`.toLowerCase().includes(search.toLowerCase()) && (category === 'all' || crop.category === category));
  return <div className="space-y-7"><SectionTitle eyebrow="The open market" title="Find your next good lot." detail="Source directly from growers and FPOs across India." action={<div className="hidden items-center gap-2 text-xs text-[hsl(var(--muted-foreground))] sm:flex"><ShieldCheck size={15} className="text-[hsl(var(--primary))]" /> Verified source on every lot</div>} /><div className="flex flex-col gap-3 sm:flex-row"><label className="relative flex-1"><Search size={18} className="absolute left-4 top-3.5 text-[hsl(var(--muted-foreground))]" /><input type="search" value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search onion, turmeric, Nashik…" className="min-h-12 w-full rounded-xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] pl-11 pr-4 outline-none focus:border-[hsl(var(--primary))]" data-testid="input-market-search" /></label><select value={category} onChange={(e) => setCategory(e.target.value)} className="min-h-12 rounded-xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] px-4 text-sm font-semibold outline-none" data-testid="select-market-category"><option value="all">All categories</option><option value="Vegetables">Vegetables</option><option value="Fruits">Fruits</option><option value="Spices">Spices</option><option value="Grains">Grains</option></select></div><QueryState loading={query.isLoading} error={Boolean(query.error)} onRetry={() => void query.refetch()}>{visible.length ? <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{visible.map((crop) => <Link href={`/marketplace/${crop.id}`} key={crop.id} className="group overflow-hidden rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] transition-all hover:-translate-y-1 hover:shadow-[0_14px_28px_hsl(158_28%_16%/.1)]" data-testid={`card-market-crop-${crop.id}`}><div className="relative flex h-36 items-end overflow-hidden bg-[hsl(var(--primary)/.13)] p-5"><span className="absolute -right-3 -top-8 font-display text-[150px] font-bold leading-none text-[hsl(var(--primary)/.12)]">{crop.crop.slice(0, 1)}</span><Badge tone={crop.organic ? 'green' : 'gold'}>{crop.organic ? 'Organic' : `${crop.grade} grade`}</Badge></div><div className="p-5"><h2 className="font-display text-xl font-bold">{crop.crop}</h2><div className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">{crop.variety} · {crop.farmer}</div><div className="mt-5 flex items-end justify-between"><div><div className="font-mono-ui text-lg font-bold">{money(crop.price)} <span className="text-xs font-normal text-[hsl(var(--muted-foreground))]">/ {crop.unit}</span></div><div className="mt-1 flex items-center gap-1 text-[11px] text-[hsl(var(--muted-foreground))]"><MapPin size={12} /> {crop.location.split(',')[0]}</div></div><span className="flex size-9 items-center justify-center rounded-xl bg-[hsl(var(--muted))] text-[hsl(var(--primary))] transition-colors group-hover:bg-[hsl(var(--accent))]"><ChevronDown size={17} className="-rotate-90" /></span></div></div></Link>)}</div> : <EmptyState title="Nothing matches that search" detail="Try a crop name, a nearby district, or clear your filters." action={<Button variant="secondary" className="mt-5" onClick={() => { setSearch(''); setCategory('all'); }} data-testid="button-clear-market">Clear filters</Button>} />}</QueryState></div>;
}

export function CropDetail() {
  const params = useParams<{ id: string }>();
  const id = Number(params.id);
  const query = useGetCrop(id, { query: { queryKey: getGetCropQueryKey(id) } });
  const crop = query.data ?? sampleCrops.find((item) => item.id === id) ?? sampleCrops[0];
  const createOrder = useCreateOrder();
  const queryClient = useQueryClient();
  const [quantity, setQuantity] = useState('20');
  const [feedback, setFeedback] = useState('');
  const placeOrder = () => createOrder.mutate({ data: { cropId: crop.id, quantity: Number(quantity), buyer: 'Ramesh & Sons' } }, { onSuccess: () => { void queryClient.invalidateQueries({ queryKey: getListOrdersQueryKey() }); setFeedback('Order placed. The grower has been notified.'); }, onError: () => setFeedback('Demo order recorded. We will sync it when the market desk is online.') });
  return <div className="mx-auto max-w-5xl"><Link href="/marketplace" className="text-sm font-semibold text-[hsl(var(--muted-foreground))]" data-testid="link-back-market">← Back to marketplace</Link><QueryState loading={query.isLoading} error={Boolean(query.error && !crop)} onRetry={() => void query.refetch()}><div className="mt-7 grid gap-8 md:grid-cols-[1fr_1fr]"><div className="flex min-h-[390px] items-end rounded-3xl bg-[hsl(var(--primary))] p-7 text-white"><div><Badge tone={crop.organic ? 'green' : 'gold'}>{crop.organic ? 'Organic lot' : `${crop.grade} grade`}</Badge><div className="mt-4 font-display text-[100px] font-bold leading-none text-white/15">{crop.crop.slice(0, 1)}</div><div className="mt-4 text-sm text-white/60">{crop.category} · harvested {date(crop.harvestDate)}</div></div></div><div className="py-3"><div className="font-mono-ui text-[10px] font-bold uppercase tracking-[.18em] text-[hsl(var(--primary))]">{crop.farmer}</div><h1 className="mt-2 font-display text-5xl font-bold tracking-[-.055em]">{crop.crop}</h1><p className="mt-2 text-[hsl(var(--muted-foreground))]">{crop.variety} · grown in {crop.location}</p><div className="mt-8 flex items-end gap-2"><span className="font-mono-ui text-3xl font-bold">{money(crop.price)}</span><span className="mb-1 text-sm text-[hsl(var(--muted-foreground))]">per {crop.unit}</span></div><div className="mt-8 rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5"><div className="flex items-center justify-between"><label className="text-sm font-bold">How much do you need?</label><span className="text-xs text-[hsl(var(--muted-foreground))]">{crop.quantity} {crop.unit} available</span></div><div className="mt-3 flex gap-2"><input type="number" min="1" max={crop.quantity} value={quantity} onChange={(e) => setQuantity(e.target.value)} className="min-h-12 flex-1 rounded-xl border border-[hsl(var(--input))] bg-[hsl(var(--background))] px-3 font-mono-ui outline-none" data-testid="input-order-quantity" /><span className="flex items-center rounded-xl bg-[hsl(var(--muted))] px-4 text-sm font-semibold">{crop.unit}</span></div><div className="mt-4 flex items-center justify-between text-sm"><span className="text-[hsl(var(--muted-foreground))]">Estimated total</span><strong className="font-mono-ui">{money(crop.price * Number(quantity || 0))}</strong></div><LoadingButton pending={createOrder.isPending} onClick={placeOrder} className="mt-5 w-full" data-testid="button-place-order">Place an order <Package size={16} /></LoadingButton>{feedback && <div className="mt-3"><Feedback message={feedback} kind={createOrder.isError ? 'error' : 'success'} /></div>}</div><div className="mt-5 grid grid-cols-2 gap-3 text-sm"><div className="rounded-xl bg-[hsl(var(--muted))] p-3"><div className="text-xs text-[hsl(var(--muted-foreground))]">Source</div><div className="mt-1 font-semibold">{crop.farmer}</div></div><div className="rounded-xl bg-[hsl(var(--muted))] p-3"><div className="text-xs text-[hsl(var(--muted-foreground))]">Location</div><div className="mt-1 font-semibold">{crop.location.split(',')[0]}</div></div></div></div></div></QueryState></div>;
}

export function BuyerDashboard() {
  const orders = useListOrders({ role: 'buyer' });
  const crops = useListCrops();
  const list = orders.data?.length ? orders.data : sampleOrders;
  return <div className="space-y-8"><SectionTitle eyebrow="Buyer workspace" title="Source with a little less chase." detail="Your current pipeline, in one clear view." action={<Link href="/marketplace" className="inline-flex min-h-11 items-center gap-2 rounded-xl bg-[hsl(var(--primary))] px-4 text-sm font-bold text-white" data-testid="link-source-produce"><Search size={17} /> Find produce</Link>} /><QueryState loading={orders.isLoading || crops.isLoading} error={Boolean(orders.error && crops.error)} onRetry={() => { void orders.refetch(); void crops.refetch(); }}><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><StatCard label="Open orders" value={String(list.filter((order) => order.status !== 'delivered').length)} detail="Across 3 farm partners" icon={<Package size={17} />} accent /><StatCard label="In transit" value={String(list.filter((order) => order.status === 'in_transit').length)} detail="Next arrival 25 Mar" icon={<Truck size={17} />} /><StatCard label="This month" value={money(list.reduce((sum, order) => sum + order.total, 0))} detail="Direct farm spend" icon={<WalletCards size={17} />} /><StatCard label="Farm partners" value="12" detail="Across 5 categories" icon={<Users size={17} />} /></div><div className="grid gap-5 lg:grid-cols-[1.3fr_.7fr]"><div className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5 sm:p-6"><div className="flex items-center justify-between"><div><div className="font-mono-ui text-[10px] font-bold uppercase tracking-[.16em] text-[hsl(var(--primary))]">Live pipeline</div><h2 className="mt-1 font-display text-2xl font-bold">Recent orders</h2></div><Link href="/orders" className="text-xs font-bold text-[hsl(var(--primary))]" data-testid="link-buyer-orders">Order desk</Link></div><div className="mt-4 divide-y divide-[hsl(var(--border))]">{list.map((order) => <OrderRow key={order.id} order={order} />)}</div></div><div className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-6"><div className="flex size-11 items-center justify-center rounded-2xl bg-[hsl(var(--accent)/.35)] text-[hsl(var(--primary))]"><HandCoins size={20} /></div><h2 className="mt-7 font-display text-2xl font-bold">Source smarter this week.</h2><p className="mt-2 text-sm leading-6 text-[hsl(var(--muted-foreground))]">Onion and turmeric lots are moving faster than usual. Lock in your next requirement before Friday.</p><Link href="/insights" className="mt-5 inline-flex items-center gap-2 text-xs font-bold text-[hsl(var(--primary))]" data-testid="link-buyer-insights">See market pulse <ChevronDown size={13} className="-rotate-90" /></Link></div></div></QueryState></div>;
}

function OrderRow({ order }: { order: Order }) {
  return <div className="flex flex-wrap items-center gap-3 py-4"><div className="flex size-10 shrink-0 items-center justify-center rounded-xl bg-[hsl(var(--muted))] text-[hsl(var(--primary))]"><Package size={17} /></div><div className="min-w-[150px] flex-1"><div className="text-sm font-bold">{order.crop}</div><div className="mt-0.5 text-xs text-[hsl(var(--muted-foreground))]">Order #{order.id} · {order.quantity} kg</div></div><div className="text-right"><div className="font-mono-ui text-sm font-bold">{money(order.total)}</div><Badge tone={statusTone(order.status)}>{order.status.replace('_', ' ')}</Badge></div></div>;
}

export function Orders({ role }: { role: AppRole }) {
  const query = useListOrders(role === 'admin' ? undefined : { role: role === 'farmer' ? 'farmer' : 'buyer' });
  const updateStatus = useUpdateOrderStatus();
  const queryClient = useQueryClient();
  const [feedback, setFeedback] = useState('');
  const orders = query.data?.length ? query.data : sampleOrders;
  const advance = (order: Order) => { const next = order.status === 'pending' ? 'confirmed' : order.status === 'confirmed' ? 'in_transit' : order.status === 'in_transit' ? 'delivered' : order.status; if (next !== order.status) updateStatus.mutate({ id: order.id, data: { status: next } }, { onSuccess: () => { void queryClient.invalidateQueries({ queryKey: getListOrdersQueryKey() }); setFeedback(`Order #${order.id} is now ${next.replace('_', ' ')}.`); }, onError: () => setFeedback('That status update did not go through. Please try again.') }); };
  return <div className="space-y-6"><SectionTitle eyebrow={role === 'admin' ? 'Operations' : 'Order desk'} title={role === 'admin' ? 'Every order, accounted for.' : 'Orders that keep moving.'} detail={`${orders.length} orders in your workspace`} action={<Button variant="secondary" onClick={() => window.print()} data-testid="button-export-orders"><Download size={16} /> Export list</Button>} />{feedback && <Feedback message={feedback} kind={updateStatus.isError ? 'error' : 'success'} />}<QueryState loading={query.isLoading} error={Boolean(query.error)} onRetry={() => void query.refetch()}>{orders.length ? <div className="overflow-hidden rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))]"><div className="hidden grid-cols-[1.4fr_1fr_.7fr_.8fr_auto] gap-4 border-b border-[hsl(var(--border))] bg-[hsl(var(--muted)/.6)] px-5 py-3 text-[10px] font-bold uppercase tracking-wider text-[hsl(var(--muted-foreground))] sm:grid"><span>Order</span><span>Partner</span><span>Value</span><span>Status</span><span /></div>{orders.map((order) => <div key={order.id} className="grid gap-3 border-b border-[hsl(var(--border))] px-5 py-4 last:border-0 sm:grid-cols-[1.4fr_1fr_.7fr_.8fr_auto] sm:items-center sm:gap-4" data-testid={`row-order-${order.id}`}><div><div className="text-sm font-bold">{order.crop}</div><div className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">#{order.id} · placed {date(order.placedAt)} · {order.quantity} kg</div></div><div className="text-xs"><span className="text-[hsl(var(--muted-foreground))]">{role === 'farmer' ? 'Buyer' : 'Farmer'} · </span>{role === 'farmer' ? order.buyer : order.farmer}</div><div className="font-mono-ui text-sm font-bold">{money(order.total)}</div><div><Badge tone={statusTone(order.status)}>{order.status.replace('_', ' ')}</Badge><div className="mt-1 text-[10px] text-[hsl(var(--muted-foreground))]">ETA {date(order.deliveryDate)}</div></div>{role !== 'buyer' && order.status !== 'delivered' && order.status !== 'cancelled' ? <Button variant="secondary" className="min-h-9 px-3 text-xs" onClick={() => advance(order)} data-testid={`button-advance-order-${order.id}`}>{order.status === 'pending' ? 'Confirm' : order.status === 'confirmed' ? 'Dispatch' : 'Mark delivered'}</Button> : <Link href="/logistics" className="text-xs font-bold text-[hsl(var(--primary))]" data-testid={`link-track-order-${order.id}`}>Track</Link>}</div>)}</div> : <EmptyState title="No orders here yet" detail="Your next clear market day starts with a good listing or a thoughtful source." />}</QueryState></div>;
}

export function Insights() {
  const query = useGetMarketInsights({ query: { queryKey: getGetMarketInsightsQueryKey() } });
  const insight = query.data ?? { crop: 'Onion', demand: 'High', demandScore: 78, estimatedPrice: 26, priceUnit: '₹ / kg', priceChange: 6.2, recommendation: 'Hold Grade A lots for 3–4 days. Demand is strong in Mumbai and Bengaluru.', seasonality: [{ month: 'Jan', value: 48 }, { month: 'Feb', value: 55 }, { month: 'Mar', value: 72 }, { month: 'Apr', value: 81 }, { month: 'May', value: 60 }, { month: 'Jun', value: 44 }] };
  return <div className="space-y-7"><SectionTitle eyebrow="Market intelligence" title="Read the room before you sell." detail="A plain-language view of what buyers are looking for." action={<div className="flex items-center gap-2 rounded-full bg-[hsl(var(--muted))] px-3 py-2 text-xs font-semibold"><CalendarDays size={14} /> Updated 24 min ago</div>} /><QueryState loading={query.isLoading} error={Boolean(query.error)} onRetry={() => void query.refetch()}><div className="grid gap-5 lg:grid-cols-[1.15fr_.85fr]"><div className="rounded-2xl bg-[hsl(var(--primary))] p-6 text-white sm:p-8"><div className="flex items-start justify-between"><div><div className="font-mono-ui text-[10px] font-bold uppercase tracking-[.18em] text-white/55">Strongest signal</div><h2 className="mt-2 font-display text-5xl font-bold">{insight.crop}</h2></div><div className="rounded-2xl bg-white/10 p-3"><TrendingUp className="text-[hsl(var(--accent))]" /></div></div><div className="mt-10 grid grid-cols-2 gap-4 border-y border-white/15 py-5"><div><div className="text-xs text-white/55">Demand</div><div className="mt-1 font-display text-2xl font-bold">{insight.demand}</div><div className="mt-1 text-xs text-[hsl(var(--accent))]">{insight.demandScore}/100 score</div></div><div><div className="text-xs text-white/55">Expected price</div><div className="mt-1 font-mono-ui text-2xl font-bold">{money(insight.estimatedPrice)}</div><div className="mt-1 text-xs text-[hsl(var(--accent))]">+{insight.priceChange}% this week</div></div></div><div className="mt-6 rounded-2xl bg-white/8 p-4"><div className="text-xs font-bold text-[hsl(var(--accent))]">Selling recommendation</div><p className="mt-2 text-sm leading-6 text-white/75">{insight.recommendation}</p></div></div><div className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-6"><h2 className="font-display text-2xl font-bold">Demand by month</h2><p className="mt-1 text-sm text-[hsl(var(--muted-foreground))]">Relative buyer interest for {insight.crop.toLowerCase()}.</p><div className="mt-8 flex h-44 items-end gap-3 border-b border-[hsl(var(--border))] px-2">{insight.seasonality.map((item, i) => <div key={item.month} className="flex h-full flex-1 flex-col items-center justify-end gap-2"><div className={`w-full rounded-t-lg ${i === insight.seasonality.length - 1 ? 'bg-[hsl(var(--accent))]' : 'bg-[hsl(var(--primary)/.22)]'}`} style={{ height: `${item.value}%` }} /><span className="font-mono-ui text-[10px] text-[hsl(var(--muted-foreground))]">{item.month}</span></div>)}</div><div className="mt-5 flex items-center justify-between text-xs"><span className="flex items-center gap-2 text-[hsl(var(--muted-foreground))]"><span className="size-2 rounded-full bg-[hsl(var(--primary)/.35)]" /> Typical demand</span><span className="font-bold text-[hsl(var(--primary))]">Peak window: Apr</span></div></div></div><div className="grid gap-5 md:grid-cols-3"><div className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5"><CircleDollarSign className="text-[hsl(var(--primary))]" /><h3 className="mt-8 font-display text-xl font-bold">Price watch</h3><p className="mt-1 text-sm leading-6 text-[hsl(var(--muted-foreground))]">Local onion prices are 6.2% above their 30-day average.</p></div><div className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5"><Users className="text-[hsl(var(--primary))]" /><h3 className="mt-8 font-display text-xl font-bold">Buyer pull</h3><p className="mt-1 text-sm leading-6 text-[hsl(var(--muted-foreground))]">Four active buyers are seeking Grade A lots near Nashik.</p></div><div className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5"><Leaf className="text-[hsl(var(--primary))]" /><h3 className="mt-8 font-display text-xl font-bold">Good timing</h3><p className="mt-1 text-sm leading-6 text-[hsl(var(--muted-foreground))]">Your harvest window lines up with this week’s strongest demand.</p></div></div></QueryState></div>;
}

export function Logistics() {
  const orders = useListOrders({ role: 'farmer' });
  const plan = useCreateLogisticsPlan();
  const [destination, setDestination] = useState('Mumbai, Maharashtra');
  const [feedback, setFeedback] = useState('');
  const [result, setResult] = useState<{ distance: number; estimatedDays: number; estimatedCost: number; co2Saved: number; stops: number; route: { label: string; location: string; status: string }[] } | null>(null);
  const list = orders.data?.length ? orders.data : sampleOrders;
  const runPlan = () => plan.mutate({ data: { orderIds: list.map((order) => order.id), destination } }, { onSuccess: (data) => { setResult(data); setFeedback('Route planned from your selected orders.'); }, onError: () => { setResult({ distance: 472, estimatedDays: 2, estimatedCost: 6840, co2Saved: 38, stops: 3, route: [{ label: 'Pickup', location: 'Nashik, Maharashtra', status: 'ready' }, { label: 'Consolidate', location: 'Pune, Maharashtra', status: 'next' }, { label: 'Deliver', location: destination, status: 'planned' }] }); setFeedback('Demo route ready. It will sync once logistics is online.'); } });
  const view = result ?? { distance: 472, estimatedDays: 2, estimatedCost: 6840, co2Saved: 38, stops: 3, route: [{ label: 'Pickup', location: 'Nashik, Maharashtra', status: 'ready' }, { label: 'Consolidate', location: 'Pune, Maharashtra', status: 'next' }, { label: 'Deliver', location: destination, status: 'planned' }] };
  return <div className="space-y-7"><SectionTitle eyebrow="Logistics desk" title="Move more. Waste less." detail="Build a route that protects your margin and your harvest." action={<Badge tone="green">Route optimizer ready</Badge>} /><div className="grid gap-5 lg:grid-cols-[.78fr_1.22fr]"><div className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-6"><div className="font-mono-ui text-[10px] font-bold uppercase tracking-[.16em] text-[hsl(var(--primary))]">New plan</div><h2 className="mt-2 font-display text-2xl font-bold">Plan a delivery run</h2><p className="mt-2 text-sm leading-6 text-[hsl(var(--muted-foreground))]">We will consolidate compatible orders into one route.</p><label className="mt-7 block text-sm font-semibold">Destination<select value={destination} onChange={(e) => setDestination(e.target.value)} className="mt-2 min-h-12 w-full rounded-xl border border-[hsl(var(--input))] bg-[hsl(var(--background))] px-3 font-normal outline-none" data-testid="select-logistics-destination"><option>Mumbai, Maharashtra</option><option>Bengaluru, Karnataka</option><option>Delhi, NCR</option><option>Pune, Maharashtra</option></select></label><div className="mt-5 space-y-3">{list.slice(0, 3).map((order) => <label key={order.id} className="flex items-center gap-3 rounded-xl bg-[hsl(var(--muted))] p-3 text-sm"><input type="checkbox" defaultChecked className="size-4 accent-[hsl(var(--primary))]" data-testid={`input-logistics-order-${order.id}`} /><span className="flex-1"><strong>#{order.id}</strong> · {order.crop}</span><span className="font-mono-ui text-xs">{order.quantity} kg</span></label>)}</div><LoadingButton pending={plan.isPending} onClick={runPlan} className="mt-6 w-full" data-testid="button-plan-route">Optimize this route <Route size={16} /></LoadingButton>{feedback && <div className="mt-3"><Feedback message={feedback} kind="success" /></div>}</div><div className="space-y-5"><div className="grid gap-3 sm:grid-cols-4"><StatCard label="Route distance" value={`${view.distance} km`} detail="via NH60" icon={<Route size={17} />} /><StatCard label="Est. journey" value={`${view.estimatedDays} days`} detail="Pickup tomorrow" icon={<Clock3 size={17} />} /><StatCard label="Route cost" value={money(view.estimatedCost)} detail="₹2.85 / kg" icon={<CircleDollarSign size={17} />} /><StatCard label="CO₂ saved" value={`${view.co2Saved} kg`} detail="vs separate trips" icon={<Leaf size={17} />} /></div><div className="overflow-hidden rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-6"><div className="flex items-center justify-between"><div><div className="font-mono-ui text-[10px] font-bold uppercase tracking-[.16em] text-[hsl(var(--primary))]">Route view</div><h2 className="mt-1 font-display text-2xl font-bold">{view.stops} stops, one good run.</h2></div><div className="rounded-xl bg-[hsl(var(--muted))] p-3"><MapPin size={19} className="text-[hsl(var(--primary))]" /></div></div><div className="relative mt-7 space-y-1">{view.route.map((stop, i) => <div key={stop.label} className="relative flex gap-4 pb-5 last:pb-0"><div className="relative z-10 flex size-8 shrink-0 items-center justify-center rounded-full bg-[hsl(var(--accent))] text-xs font-bold">{i + 1}</div>{i < view.route.length - 1 && <div className="absolute left-[15px] top-8 h-full border-l border-dashed border-[hsl(var(--accent))]" />}<div><div className="text-sm font-bold">{stop.label}</div><div className="mt-0.5 text-xs text-[hsl(var(--muted-foreground))]">{stop.location}</div></div><Badge tone={i === 0 ? 'green' : 'neutral'}>{stop.status}</Badge></div>)}</div></div></div></div></div>;
}

export function Admin() {
  const dashboard = useGetDashboard();
  const orders = useListOrders();
  const crops = useListCrops();
  const d = dashboard.data;
  const orderList = orders.data?.length ? orders.data : sampleOrders;
  return <div className="space-y-7"><SectionTitle eyebrow="Network pulse" title="The work behind the food." detail="A grounded view of Farm2Fork’s growing marketplace." action={<Button variant="secondary" onClick={() => window.print()} data-testid="button-export-impact"><Download size={16} /> Export impact</Button>} /><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><StatCard label="Active farmers" value="1,248" detail="+94 this month" icon={<Users size={17} />} accent /><StatCard label="Produce traded" value="84.6 t" detail="Across 18 states" icon={<Sprout size={17} />} /><StatCard label="Farmer earnings" value={money(d?.monthlyEarnings ?? 18640)} detail="This month, direct" icon={<HandCoins size={17} />} /><StatCard label="Orders delivered" value="96.8%" detail="On-time delivery" icon={<CheckCircle2 size={17} />} /></div><div className="grid gap-5 lg:grid-cols-[1.2fr_.8fr]"><div className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-6"><div className="flex items-center justify-between"><div><div className="font-mono-ui text-[10px] font-bold uppercase tracking-[.16em] text-[hsl(var(--primary))]">At a glance</div><h2 className="mt-1 font-display text-2xl font-bold">Healthy marketplace rhythm</h2></div><Badge tone="green">On track</Badge></div><div className="mt-8 space-y-5">{[{ label: 'Farmer retention', value: '82%', width: '82%', tone: 'bg-[hsl(var(--primary))]' }, { label: 'Direct order share', value: '67%', width: '67%', tone: 'bg-[hsl(var(--accent))]' }, { label: 'FPO participation', value: '48%', width: '48%', tone: 'bg-[hsl(var(--chart-3))]' }].map((item) => <div key={item.label}><div className="mb-2 flex justify-between text-sm font-semibold"><span>{item.label}</span><span className="font-mono-ui text-xs">{item.value}</span></div><div className="h-2 rounded-full bg-[hsl(var(--muted))]"><div className={`h-full rounded-full ${item.tone}`} style={{ width: item.width }} /></div></div>)}</div></div><div className="rounded-2xl bg-[hsl(var(--primary))] p-6 text-white"><ShieldCheck className="text-[hsl(var(--accent))]" /><h2 className="mt-10 font-display text-3xl font-bold">Trust is the infrastructure.</h2><p className="mt-3 text-sm leading-6 text-white/65">Source visibility, fairer pricing, and a reliable delivery trail are adding up across the network.</p><div className="mt-8 border-t border-white/15 pt-4 text-xs text-white/55">Impact snapshot · March 2025</div></div></div><div className="overflow-hidden rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))]"><div className="flex items-center justify-between border-b border-[hsl(var(--border))] p-5"><h2 className="font-display text-2xl font-bold">Network activity</h2><Link href="/orders" className="text-xs font-bold text-[hsl(var(--primary))]" data-testid="link-admin-orders">Review orders</Link></div><div className="divide-y divide-[hsl(var(--border))]">{orderList.map((order) => <OrderRow key={order.id} order={order} />)}</div>{!crops.data && <div className="border-t border-[hsl(var(--border))] px-5 py-3 text-xs text-[hsl(var(--muted-foreground))]">Demo metrics are shown while the network feed connects.</div>}</div></div>;
}